local function dumpInstance(instance, log, indent)
    indent = indent or S(189)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(139) .. child.Name .. S(74)
        if child:IsA(S(135)) then
            line = line .. string.format(
                S(80),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(219)) then
            line = line .. string.format(S(55), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(93)) or child:IsA(S(236)) then
            line = line .. S(39)
        end
        log(line)
        for attrName, attrValue in pairs(child:GetAttributes()) do
            log(indent .. S(128) .. attrName .. S(208) .. tostring(attrValue))
        end
        dumpInstance(child, log, indent .. S(163))
    end
end
return dumpInstance
end
